package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.widget.*;import com.irwi.fincapp.session.SessionManager;
public class SettingsActivity extends Activity{public void onCreate(android.os.Bundle b){super.onCreate(b);SessionManager s=new SessionManager(this);LinearLayout l=BaseUi.root(this);l.addView(BaseUi.title(this,"Developer settings"));l.addView(BaseUi.text(this,"Backend URL is hidden from the user flow. Change it here only for testing.",18));EditText url=BaseUi.input(this,"Backend API URL");url.setText(s.baseUrl());Button save=BaseUi.btn(this,"Save backend URL");Button logout=BaseUi.btn(this,"Logout");l.addView(url);l.addView(save);l.addView(logout);save.setOnClickListener(v->{s.setBaseUrl(url.getText().toString().trim());BaseUi.toast(this,"Saved");finish();});logout.setOnClickListener(v->{s.logout();finish();});}}
